// All names, identifiers and balances are synthetic. No municipal source bytes.
import {createHash} from 'node:crypto';
import {ID,CONTRACT,principal as original,session} from './native-employee-synthetic.js';
import {NATIVE_LEAVE_VERSION,NATIVE_LEAVE_POLICY_VERSION,nativeLeaveBalances} from '../../assets/native-leave-model.js';
import {nativeLeaveSerialized} from '../../lib/internal-native-leave.js';
export {ID,CONTRACT,session};
export const principal={...original,tenant:{...original.tenant,effectiveCapabilities:['workforce.employee.read','actions.read','leave.request.all.manage','leave.request.all.read','leave.request.restricted.read','leave.request.restricted.decide']}};
export const annual=(patch={})=>({reasonCode:'19',policyVersionId:NATIVE_LEAVE_POLICY_VERSION,policyRuleId:'annual-ordinary',startsOn:'2026-10-01',endsOn:'2026-10-02',durationUnit:'calendar_day',startsAtLocal:null,endsAtLocal:null,confidentiality:'standard',employeeNote:null,...patch});
export const profile=(patch={})=>({reasonCode:'19',year:2026,durationUnit:'calendar_day',mode:'confirmed',entitledUnits:20,legalReference:'Resolución sintética QA',reason:'Saldo declarado sintético para revisión.',...patch});
export const command=(patch={})=>({contractId:CONTRACT,identityToken:'e'.repeat(64),scopeVersion:'d'.repeat(64),employmentVersion:'b'.repeat(64),snapshotVersion:'a'.repeat(64),command:'create',entityId:null,expectedVersion:0,payload:annual(),reason:null,evidenceStatus:null,manualValidationConfirmed:false,...patch});
export const receipt=(body=command(),patch={})=>({version:NATIVE_LEAVE_VERSION,command:body.command,contractId:body.contractId,entityId:body.entityId??ID,entityVersion:body.expectedVersion+1,status:({create:'draft',update_draft:'draft',submit:'submitted',approve:'approved',reject:'rejected',cancel:'cancelled',profile_propose:'pending',profile_approve:'approved',profile_reject:'rejected'})[body.command],payload:body.payload??annual(),requestSha256:createHash('sha256').update(nativeLeaveSerialized(body)).digest('hex'),replayed:false,payrollModified:false,...patch});
export const bootstrap=()=>({version:NATIVE_LEAVE_VERSION,scopeVersion:'d'.repeat(64),snapshotVersion:'a'.repeat(64),subject:{contractId:CONTRACT,legajo:'5001',employeeName:'PERSONA SINTÉTICA QA',identityToken:'e'.repeat(64),sourceCutoff:null,origin:'MUNICONTROL',registrationId:ID,registeredAt:'2026-09-23T12:00:00Z'},employment:{version:'b'.repeat(64),revision:0,appliedAt:null,intervals:[{startDate:'2026-09-21',endDate:null}],today:'2026-10-01',status:'active'},permissions:{canCreate:true,canProposeProfile:true},complete:true,requests:[],profileProposals:[],balances:[]});
export function entity(id=ID,payload=annual(),commands=['create'],kind='request'){
 const statuses={create:'draft',update_draft:'draft',submit:'submitted',approve:'approved',reject:'rejected',cancel:'cancelled',profile_propose:'pending',profile_approve:'approved',profile_reject:'rejected'};
 const history=commands.map((command,i)=>({version:i+1,command,status:statuses[command],payload:structuredClone(payload),reason:['create','update_draft'].includes(command)?null:'Decisión independiente sintética QA',evidenceStatus:command==='approve'?'verified':null,manualValidationConfirmed:['approve','profile_approve'].includes(command),recordedAt:`2026-10-01T12:00:${String(i).padStart(2,'0')}Z`,actorLabel:i===0?'Preparador sintético':'Revisor sintético'}));
 const status=history.at(-1).status;
 return{id,version:history.length,status,payload,createdAt:history[0].recordedAt,authorLabel:history[0].actorLabel,canUpdate:kind==='request'&&status==='draft',canSubmit:kind==='request'&&status==='draft',canReview:kind==='request'?status==='submitted':status==='pending',canCancel:kind==='request'&&['draft','submitted','approved'].includes(status),history};
}
export function withRows(requests=[],profileProposals=[]){const b=bootstrap();b.requests=requests;b.profileProposals=profileProposals;b.balances=nativeLeaveBalances(profileProposals.filter(p=>p.status==='approved').map(p=>p.payload),requests.map(p=>({id:p.id,status:p.status,payload:p.payload})),{complete:true});return b;}
